example_queries:
# Data sources per type
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?type (COUNT(?ds) AS ?n) WHERE {
  ?ds oaire:datasourceType ?type .
} GROUP BY ?type ORDER BY DESC(?n)

# OpenAIRE compatibility levels
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?level (COUNT(?ds) AS ?n) WHERE {
  ?ds oaire:openaireCompatibility ?level .
} GROUP BY ?level ORDER BY DESC(?n)

# Data repositories and their websites
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?ds ?name ?website WHERE {
  ?ds oaire:datasourceType "Data Repository" ; oaire:officialName ?name ; oaire:website ?website .
} LIMIT 20

# Institutional repositories
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?ds ?name WHERE {
  ?ds oaire:datasourceType "Institutional Repository" ; oaire:officialName ?name .
} LIMIT 20

# Data sources whose English name differs from the official one
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?official ?english WHERE {
  ?ds oaire:officialName ?official ; oaire:englishName ?english .
  FILTER(?official != ?english)
} LIMIT 20
